<script setup lang="ts">import {ref,computed,watch,onMounted} from 'vue';import {go} from '../router';import {models} from '../stores/models';import {spaces} from '../stores/spaces';import {studies} from '../stores/studies';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),model=ref('demo-model'),space=ref('demo-space'),r=ref(24),p=ref(6),m=ref(12),seed=ref(20261112);const matching=computed(()=>spaces.items.value.filter(s=>s.model_id===model.value));watch(model,()=>{space.value=matching.value[0]?.id||''});const {error,busy,act}=useTask();onMounted(()=>Promise.all([models.load(),spaces.load(),studies.load()]));function submit(){act(async()=>{await studies.create({name:name.value,model_id:model.value,space_id:space.value,trajectories:r.value,levels:p.value,power:m.value,seed:seed.value});name.value=''})}function execute(id:string){act(async()=>{const run=await runs.create({study_id:id});go('/results?run='+run.id)})}</script><template><PageHeading index="03 / 采样研究" title="把预算、网格与随机种子写入底稿。" note="Morris每条轨迹d+1次评估；Sobol基础行n=2^m，实际(d+2)n次评估。两者使用同一锁定模型与因子范围，不提供置信区间。"/><Notice :message="error"/><div class="two-col"><section><article class="study-row" v-for="s in studies.items.value" :key="s.id"><p class="eyebrow">LOCKED EXPERIMENT</p><h2>{{s.name}}</h2><dl><div><dt>Morris轨迹 / p</dt><dd>{{s.trajectories}} / {{s.levels}}</dd></div><div><dt>Sobol指数m</dt><dd>{{s.power}}</dd></div><div><dt>seed</dt><dd class="seed-number">{{s.seed}}</dd></div></dl><button v-if="canWrite()" :disabled="busy" @click="execute(s.id)">执行后台敏感度试验 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>新建采样研究</h2><label>研究名称<input v-model="name" required minlength="2"></label><label>响应模型<select v-model="model"><option v-for="s in models.items.value" :value="s.id" :key="s.id">{{s.name}}</option></select></label><label>对应因子空间<select v-model="space"><option v-for="s in matching" :value="s.id" :key="s.id">{{s.name}}</option></select></label><div class="form-pair"><label>Morris轨迹r<input type="number" v-model.number="r" min="2" max="128" required></label><label>偶数网格p<input type="number" v-model.number="p" min="2" max="20" step="2" required></label></div><label>Sobol指数m / 2–16<input type="number" v-model.number="m" min="2" max="16" required></label><label>固定seed<input type="number" v-model.number="seed" min="0" max="4294967295" required></label><button :disabled="busy">保存采样研究</button></form></div></template>
